function sessionTable(rows){
  return table(['Course and group','Date and time','Room','Instructor','Attendance',''],rows.map(session=>{
    const editable=can('attendance.update')&&(state.user.role==='admin'||session.instructor_id===state.user.id);
    return `<tr><td><strong>${esc(session.course)}</strong><div class="subtext">${esc(session.group_name)}</div></td><td>${formatDate(session.session_date)}<div class="subtext">${esc([session.start_time,session.end_time].filter(Boolean).join('–')||'Time not set')}</div></td><td>${esc(session.room||'—')}</td><td>${esc(session.instructor)}</td><td>${session.marked?`${session.present||0} present / ${session.marked} marked`:'Not marked'}</td><td class="table-actions">${button('view-attendance',editable?'Take attendance':'View attendance',{primary:editable,small:true,attrs:`data-id="${esc(session.id)}"`})}${can('sessions.update')&&(state.user.role==='admin'||session.instructor_id===state.user.id)?button('edit-session','Edit',{small:true,attrs:`data-id="${esc(session.id)}"`}):''}${can('sessions.delete')?button('archive-session','Archive',{small:true,danger:true,attrs:`data-id="${esc(session.id)}"`}):''}</td></tr>`;
  }),'No sessions match these filters','Try another date range or add a session.')
}
