  return `${pageHeading('Assignments','Grant instructor access to specific course and group combinations.',button('add-assignment','Assign instructor',{primary:true}))}<section class="panel">${table(['Instructor','Course','Group',''],rows.map(assignment=>`<tr><td><strong>${esc(assignment.instructor)}</strong></td><td>${esc(assignment.course)}</td><td>${esc(assignment.group_name)}</td><td>${button('remove-assignment','Remove',{small:true,danger:true,attrs:`data-id="${esc(assignment.id)}"`})}</td></tr>`),'No instructor assignments','Assign an instructor to the course groups they teach.')}</section>`;
