  const modes=[...(allowStudents?[['students','Student records']]:[]),...(allowAttendance?[['attendance','Session attendance']]:[])];
  const modeOptions=modes.map(([value,label])=>`<option value="${value}" ${state.importType===value?'selected':''}>${label}</option>`).join('');
  let target='';
  if(state.importType==='attendance')target=`<label class="field"><span>Attendance session</span><select id="import-session"><option value="">Choose a session…</option>${sessions.map(session=>`<option value="${esc(session.id)}" ${state.importSession===session.id?'selected':''}>${esc(`${session.session_date} · ${session.course} · ${session.group_name} · ${session.room||'No room'}`)}</option>`).join('')}</select><small>Only sessions you can update are shown. Attendance imports update roster records already created for that session.</small></label>`;
