function guessColumn(headers,field){
  const normalized=headers.map(value=>String(value??'').toLocaleLowerCase().replace(/[^a-z0-9]/g,''));
  const terms={full_name:['studentname','fullname','name'],status:['status','attendance','attendancestatus','presence']};
  const index=normalized.findIndex(header=>(terms[field]||[]).some(term=>header===term||header.includes(term)));return index<0?-1:index;
}
function importMappingMarkup(){
  const matrix=state.importMatrix||[],headers=matrix[0]||[];if(!headers.length)return '';
  const fields=state.importType==='students'?[['full_name','Student Name',true]]:[['full_name','Student Name',true],['status','Attendance status',true]];
  const controls=fields.map(([key,label,required])=>{const guess=guessColumn(headers,key),options=[{value:'-1',label:'Choose a source column…'},...headers.map((header,index)=>({value:String(index),label:`${index+1}. ${String(header||`Column ${index+1}`)}`}))];return htmlField(label,`map-${key}`,{required,value:String(guess),options,hint:'Required field'});}).join('');
  return `<section class="mapping-step"><header class="panel-head"><div><span class="eyebrow">STEP 2</span><h2>Check extracted rows and map columns</h2><p>Edit the tab-separated preview if a PDF or spreadsheet column was extracted incorrectly.</p></div></header><label class="field"><span>Imported data</span><textarea id="import-text" rows="7" spellcheck="false">${esc(rowsToTsv(matrix))}</textarea></label><div class="mapping-grid">${controls}</div>${state.importType==='attendance'?`<p class="help-text">The selected session supplies the course and group. Map student names and their Present/Absent status.</p>`:`<p class="help-text">Map Student Name. Course and Group are selected above in this workspace; values in the uploaded file are ignored.</p>`}<div class="mapping-actions">${button('update-import-matrix','Update column headings')}${button('preview-import','Validate and preview',{primary:true})}</div></section>`;
}
function clearImportValidation(){state.importPreview=null;const target=document.querySelector('#import-preview');if(target){target.hidden=true;target.innerHTML='';}}
function renderImportMapping(){const target=document.querySelector('#import-mapping');if(target)target.innerHTML=importMappingMarkup();}
function startImportMapping(matrix,source){
  if(!Array.isArray(matrix)||matrix.length<2)throw new Error('The file needs a header row and at least one data row.');if(matrix.length>2001)throw new Error('The import is limited to 2,000 rows.');if(Math.max(...matrix.slice(0,2001).map(row=>row.length))>50)throw new Error('The import is limited to 50 columns.');
  state.importMatrix=matrix;state.importSource=source;state.importPreview=null;renderImportMapping();const preview=document.querySelector('#import-preview');if(preview){preview.hidden=true;preview.innerHTML='';}
}
async function parsePdfFile(file){
  const pdfjs=await import(new URL('/vendor/pdf.mjs',location.origin).href);pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';const documentTask=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,enableXfa:false});const pdf=await documentTask.promise;if(pdf.numPages>10)throw new Error('PDF import is limited to 10 pages. Split a longer report into smaller files.');let rows=[];
  for(let number=1;number<=pdf.numPages;number++){const page=await pdf.getPage(number),content=await page.getTextContent({includeMarkedContent:false}),lines=pdfTextItemsToRows(content.items);rows.push(...lines);if(rows.length>2001)throw new Error('The PDF contains more than 2,000 extracted rows. Narrow the document before importing.');}
  if(rows.length<2)throw new Error('This PDF has no selectable table text. Scanned images need OCR; nothing was imported.');return rows;
}
async function parseImportFile(file){
  if(!file)return;state.importMatrix=null;state.importPreview=null;state.importWorkbook=null;for(const selector of ['#import-mapping','#import-preview','#workbook-preview']){const host=document.querySelector(selector);if(host){host.innerHTML='';if(selector==='#import-preview')host.hidden=true;}}if(file.size>5*1024*1024)throw new Error('Choose a file smaller than 5 MB.');const extension=file.name.split('.').pop().toLowerCase();let matrix;
  if(extension==='csv'||file.type==='text/csv'){matrix=parseCSVMatrix(await file.text());state.importWorkbook=null;startImportMapping(matrix,'CSV');return;}
  if(extension==='pdf'||file.type==='application/pdf'){state.importWorkbook=null;matrix=await parsePdfFile(file);startImportMapping(matrix,'PDF');return;}
  if(extension==='xlsx'||extension==='xls'||file.type.includes('spreadsheet')){const loading=document.querySelector('#workbook-preview');if(loading)loading.innerHTML='<section class="panel loading-state">Loading workbook preview…</section>';const XLSX=await import('xlsx'),workbook=readWorkbook(XLSX,await file.arrayBuffer());state.importWorkbook={XLSX,workbook,fileName:file.name};state.importWorkbookSheet=0;state.importMatrix=null;state.importPreview=null;const preview=document.querySelector('#workbook-preview');if(preview)preview.innerHTML=`${workbookViewerMarkup(state.importWorkbook,file.name,0,'import')}${button('continue-xlsx-mapping','Continue to column mapping',{primary:true,extra:'xlsx-continue'})}`;return;}
  throw new Error('Choose a CSV, XLSX, or selectable-text PDF file.');
}
function workbookMatrix(sheetIndex){const imported=state.importWorkbook;if(!imported)return[];return workbookImportMatrix(imported.XLSX,imported.workbook,sheetIndex);}

function importDecisionSelect(row,index){
  if(row.issue)return badge(row.issue,'absent');
  if(state.importType==='attendance')return `<select aria-label="Import action for row ${row.row}" data-import-decision="${index}"><option value="update" selected>Apply status</option><option value="skip">Skip</option></select>`;
  if(row.duplicate==='possible_name')return `<select aria-label="Possible duplicate action for row ${row.row}" data-import-decision="${index}"><option value="skip" selected>Skip possible duplicate</option><option value="insert">Import as a separate student</option></select>`;
  return badge('Add new student','active');
}
function renderImportPreview(data){
  state.importPreview=data;const target=document.querySelector('#import-preview');if(!target)return;target.hidden=false;const total=data.rows?.length||0,ready=data.valid||0,issues=data.issues||0;
  const previewRows=(data.rows||[]).map((row,index)=>{if(state.importType==='attendance'){return `<tr><td>${row.row}</td><td><strong>${esc(row.full_name)}</strong><div class="subtext">${esc(row.existing?.full_name||'Not found in session roster')}</div></td><td>${badge(row.existing?.status==='present'?'Present':row.existing?.status==='absent'?'Absent':'—',row.existing?.status||'neutral')}</td><td>${row.status?badge(row.status==='present'?'Present':'Absent',row.status):'—'}</td><td>${importDecisionSelect(row,index)}</td></tr>`;}
    const existing=row.existing?`${row.existing.full_name} · ${row.existing.course||'No course'} / ${row.existing.group}`:row.duplicate==='possible_name'?'Another imported or existing record may have the same name and group.':'—';return `<tr><td>${row.row}</td><td>${esc(existing)}</td><td><strong>${esc(row.full_name)}</strong></td><td>${esc(row.course||'—')}<div class="subtext">${esc(row.group||'—')}</div></td><td>${importDecisionSelect(row,index)}</td></tr>`;});
  const heads=state.importType==='attendance'?['Row','Student name','Current status','Imported status','Action']:['Row','Existing record and possible match','Imported student','Selected course and group','Action'];
  target.innerHTML=`<section class="preview-step"><header class="panel-head"><div><span class="eyebrow">STEP 3</span><h2>Validation and duplicate review</h2><p>${ready} rows ready · ${issues} need correction or will be skipped · ${total} rows total</p></div><button class="btn primary" type="button" data-action="confirm-import" ${ready?'':'disabled'}>Confirm import</button></header>${table(heads,previewRows,'No data rows to import','Return to the file and check its table content.')}</section>`;
}
async function runImportPreview(){
  const matrix=state.importMatrix?parseDelimitedText(document.querySelector('#import-text')?.value||''):null;if(!matrix)throw new Error('Choose an import file first.');const mappingForm=document.querySelector('#import-mapping'),mapping={};for(const select of mappingForm.querySelectorAll('[name^="map-"]'))mapping[select.name.slice(4)]=select.value;
  if(state.importType==='students'){
    if(!can('students.import'))throw new Error('Student records can only be imported by administrators.');const rows=mapMatrixToStudents(matrix,mapping);if(!rows.length)throw new Error('No non-empty student rows were found.');const courseId=document.querySelector('#import-course')?.value,groupId=document.querySelector('#import-group')?.value;if(!courseId||!groupId)throw new Error('Choose an active Course and Group in the workspace.');state.importCourse=courseId;state.importGroup=groupId;const data=await send('/api/import/preview','POST',{course_id:courseId,group_id:groupId,rows});renderImportPreview(data);return;
  }
  if(!can('attendance.update'))throw new Error('You cannot import attendance for this account.');const sessionId=document.querySelector('#import-session')?.value;if(!sessionId)throw new Error('Choose the session to receive these attendance statuses.');state.importSession=sessionId;const rows=mapMatrixToAttendance(matrix,mapping);if(!rows.length)throw new Error('No attendance rows were found.');const data=await send('/api/import/attendance/preview','POST',{session_id:sessionId,rows});renderImportPreview(data);
}
async function confirmImport(){
  const preview=state.importPreview;if(!preview)throw new Error('Review the import preview first.');const rows=preview.rows.filter(row=>!row.issue).map((row,index)=>{const select=document.querySelector(`[data-import-decision="${preview.rows.indexOf(row)}"]`),decision=select?.value||(state.importType==='attendance'?'update':'insert');return {...row,decision,allow_possible_duplicate:row.duplicate==='possible_name'&&decision==='insert'};});if(!rows.some(row=>row.decision!=='skip'))throw new Error('Choose at least one row to import.');
  const result=state.importType==='attendance'?await send('/api/import/attendance/commit','POST',{session_id:state.importSession,rows,source:state.importSource}):await send('/api/import/commit','POST',{course_id:state.importCourse,group_id:state.importGroup,rows,source:state.importSource});const parts=[];if(result.imported)parts.push(`${result.imported} student records added`);if(result.updated)parts.push(`${result.updated} records updated`);if(result.skipped)parts.push(`${result.skipped} skipped`);notify(parts.join(' · ')||'Import completed.');state.importPreview=null;state.importMatrix=null;state.view=state.importType==='attendance'?'sessions':'students';await renderApp();
}
function paramsFromForm(form){const params=new URLSearchParams();for(const[key,value]of new FormData(form))if(String(value).trim())params.set(key,String(value).trim());return params;}
async function loadAuditPage(offset,formValues=state.auditFilters||{}){
  const params=new URLSearchParams({...formValues,limit:'50',offset:String(offset)});const [result,users]=await Promise.all([api(`/api/audit?${params}`),api('/api/users')]);state.auditOffset=offset;state.auditFilters=formValues;state.auditUsers=users;document.querySelector('#content').innerHTML=auditMarkup(result,users);
}
async function downloadXlsx(){
  const rows=await api(`/api/export/attendance.json?${new URLSearchParams(state.reportFilters||{})}`),XLSX=await import('xlsx');if(!rows.length){notify('No attendance records match these filters.',true);return;}
  const sheets=buildConsolidatedAttendanceSheets(rows),book=XLSX.utils.book_new(),safe=value=>{const text=String(value??'');return /^[\u0000-\u0020]*[=+\-@]/.test(text)?`'${text}`:value;};for(const[name,values]of Object.entries(sheets)){const sheet=XLSX.utils.aoa_to_sheet(values.map(row=>row.map(safe)));sheet['!cols']=values[0].map(label=>({wch:Math.min(36,Math.max(String(label).length+2,14))}));if(sheet['!ref'])sheet['!autofilter']={ref:sheet['!ref']};XLSX.utils.book_append_sheet(book,sheet,name);}XLSX.writeFileXLSX(book,'attendance.xlsx');notify(`${rows.length} attendance records exported across ${Object.keys(sheets).length} sheets.`);
}
function pdfReportHtml(rows){
  const sessionMap=new Map();for(const row of rows){if(!sessionMap.has(row.session_id))sessionMap.set(row.session_id,{...row,students:[]});sessionMap.get(row.session_id).students.push(row);}
  const present=rows.filter(row=>row.status==='present').length,rate=rows.length?Math.round(present*100/rows.length):0;
  const groups=[...sessionMap.values()].map(session=>`<section class="session"><h2>${esc(session.course)} · ${esc(session.group_name)}</h2><p><strong>Instructor:</strong> ${esc(session.instructor)} &nbsp; <strong>Date:</strong> ${esc(session.session_date)} &nbsp; <strong>Time:</strong> ${esc([session.start_time,session.end_time].filter(Boolean).join('–')||'—')} &nbsp; <strong>Room:</strong> ${esc(session.room||'—')}</p><table><thead><tr><th>#</th><th>Student name</th><th>Attendance status</th></tr></thead><tbody>${session.students.map((student,index)=>`<tr><td>${index+1}</td><td>${esc(student.student)}</td><td>${student.status==='present'?'Present':'Absent'}</td></tr>`).join('')}</tbody></table></section>`).join('');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(state.workspaceName)} attendance report</title><style>body{font:12px/1.45 Arial,sans-serif;color:#202923;margin:30px}header{border-bottom:2px solid #2f624d;margin-bottom:20px;padding-bottom:12px}h1{font-size:20px;margin:4px 0}h2{font-size:14px;margin:0 0 6px}p{margin:4px 0 10px}.summary{display:flex;gap:28px;margin:14px 0 22px}.session{page-break-inside:avoid;margin:0 0 25px}.session>p{color:#46534b}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid #d8ded9;padding:6px 8px}th{background:#f1f4f1;font-weight:600}.print-actions{margin:16px 0 25px}@page{size:A4 landscape;margin:15mm}@media print{body{margin:0}.print-actions{display:none}}</style></head><body><header><p>${esc(state.workspaceName)}</p><h1>Attendance report</h1><p>Generated ${esc(new Date().toLocaleString())}</p></header><div class="summary"><span><strong>${new Set(rows.map(row=>row.session_id)).size}</strong> sessions</span><span><strong>${rows.length}</strong> attendance records</span><span><strong>${present}</strong> present</span><span><strong>${rows.length-present}</strong> absent</span><span><strong>${rate}%</strong> attendance rate</span></div><div class="print-actions"><button onclick="window.print()">Print / Save as PDF</button></div>${groups||'<p>No attendance records match the selected filters.</p>'}</body></html>`;
}
async function printReport(){const printWindow=window.open('about:blank','_blank');if(!printWindow){throw new Error('Allow pop-ups for this site to print the report.');}try{const rows=await api(`/api/export/attendance.json?${new URLSearchParams(state.reportFilters||{})}`);if(!rows.length){printWindow.close();throw new Error('No attendance records match these filters.');}printWindow.document.open();printWindow.document.write(pdfReportHtml(rows));printWindow.document.close();printWindow.focus();setTimeout(()=>printWindow.print(),350);}catch(error){printWindow.close();throw error;}}
async function takeAttendance(sessionId){
  const [session,roster]=await Promise.all([api(`/api/sessions/${encodeURIComponent(sessionId)}`),api(`/api/sessions/${encodeURIComponent(sessionId)}/attendance`)]),readOnly=!can('attendance.update')||(state.user.role!=='admin'&&session.instructor_id!==state.user.id),preservedRecords=roster.filter(row=>row.student_key===null);let records=roster.filter(row=>readOnly||row.student_key!==null).map(row=>({...row}));
  const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal attendance-modal" role="dialog" aria-modal="true" aria-labelledby="attendance-title"><header class="modal-head"><div><h2 id="attendance-title">${readOnly?'Attendance records':'Take attendance'}</h2><p class="subtext">${esc(session.course)} · ${esc(session.group_name)} · ${esc(formatDate(session.session_date))} · ${esc(session.room||'Room not set')}</p><p class="subtext">${esc([session.start_time,session.end_time].filter(Boolean).join('–')||'Time not set')} · ${esc(session.instructor)}</p></div><button type="button" class="modal-close" aria-label="Close dialog">×</button></header><div class="attendance-tools">${records.length?`<label><span class="sr-only">Find a student</span><input id="attendance-search" type="search" placeholder="Student name"></label>`:''}${readOnly?'':`<button class="btn small" type="button" id="all-present">Mark all present</button>`}<span class="spacer"></span><span class="attendance-count" id="attendance-count"></span></div><div class="attendance-list" id="attendance-list">${records.map((record,index)=>attendanceRow(record,index,readOnly)).join('')||emptyState('No students in this group','Add students before recording attendance.')}</div>${!readOnly&&preservedRecords.length?`<section class="historical-attendance"><strong>${preservedRecords.length} preserved historical record${preservedRecords.length===1?'':'s'}</strong><p>These attendance marks remain in the session history for students whose records were removed.</p>${preservedRecords.map(record=>`<div class="attendance-row"><span aria-hidden="true">—</span><div class="attendance-person"><strong>${esc(record.full_name)}</strong></div>${badge(record.status==='present'?'Present':'Absent',record.status)}</div>`).join('')}</section>`:''}${readOnly?'':`<footer class="modal-footer"><span class="form-message" id="attendance-message" role="status"></span><button type="button" class="btn primary" id="save-attendance" ${records.length?'':'disabled'}>Save attendance</button></footer>`}</section>`;
  document.body.append(wrap);const close=()=>wrap.remove();wrap.querySelector('.modal-close').onclick=close;wrap.addEventListener('click',event=>{if(event.target===wrap)close();});const search=wrap.querySelector('#attendance-search');if(search)search.addEventListener('input',()=>{const query=search.value.toLocaleLowerCase();wrap.querySelectorAll('.attendance-row').forEach(row=>row.hidden=!row.dataset.search.includes(query));});
  if(!readOnly){const initialStatuses=records.map(row=>row.status),button=wrap.querySelector('#save-attendance');const updateCount=()=>{const present=records.filter(row=>row.status==='present').length,dirty=records.some((row,index)=>row.status!==initialStatuses[index]);wrap.querySelector('#attendance-count').textContent=`${present} present · ${records.length-present} absent · ${dirty?'Unsaved changes':'All changes saved'}`;button.disabled=!dirty;};updateCount();wrap.querySelector('#all-present').onclick=()=>{records=records.map(row=>({...row,status:'present'}));wrap.querySelector('#attendance-list').innerHTML=records.map((row,index)=>attendanceRow(row,index,false)).join('');updateCount();};wrap.querySelector('#attendance-list').addEventListener('click',event=>{const control=event.target.closest('[data-attendance-status]');if(!control)return;const index=Number(control.dataset.index);records[index].status=control.dataset.attendanceStatus;const row=control.closest('.attendance-row');row.querySelectorAll('[data-attendance-status]').forEach(item=>{const selected=item.dataset.attendanceStatus===records[index].status;item.setAttribute('aria-pressed',String(selected));item.className=`${selected?'selected ':''}${item.dataset.attendanceStatus}`;});updateCount();});wrap.querySelector('#save-attendance').onclick=async()=>{const message=wrap.querySelector('#attendance-message');button.disabled=true;button.textContent='Saving…';try{await send(`/api/sessions/${encodeURIComponent(sessionId)}/attendance`,'PUT',{attendance:records.map(row=>({student_key:row.student_key,status:row.status}))});close();notify('Attendance saved.');await renderView();}catch(error){message.textContent=error.message;button.textContent='Save attendance';updateCount();}};}
}
function attendanceRow(record,index,readOnly){const phrase=String(record.full_name||'').toLocaleLowerCase();return `<div class="attendance-row" data-search="${esc(phrase)}"><span class="attendance-number">${String(index+1).padStart(2,'0')}</span><div class="attendance-person"><strong>${esc(record.full_name)}</strong></div>${readOnly?badge(record.status==='present'?'Present':'Absent',record.status):`<div class="attendance-actions"><button type="button" data-index="${index}" data-attendance-status="present" aria-pressed="${record.status==='present'}" class="${record.status==='present'?'selected present':''}">${record.status==='present'?'✓ ':''}Present</button><button type="button" data-index="${index}" data-attendance-status="absent" aria-pressed="${record.status==='absent'}" class="${record.status==='absent'?'selected absent':''}">${record.status==='absent'?'× ':''}Absent</button></div>`}</div>`;}

async function handleAction(action,control){
  switch(action){
    case 'logout':return logout();
    case 'retry-view':return renderView();
    case 'delete-selected-students':{const student_ids=[...document.querySelectorAll('.student-select:checked')].map(input=>input.value);if(!student_ids.length)throw new Error('Select at least one student.');if(!confirm(`Permanently remove ${student_ids.length} selected student record${student_ids.length===1?'':'s'}? Their historical attendance marks will remain in reports, and an administrator-only recovery snapshot will be created.`))return;const result=await send('/api/students/delete-selected','POST',{student_ids});notify(`${result.deleted} student records removed; ${result.attendance} historical attendance marks retained.`);return renderApp();}
    case 'delete-selected-attendance':{const attendance_ids=[...document.querySelectorAll('.attendance-select:checked')].map(input=>input.value);if(!attendance_ids.length)throw new Error('Select at least one attendance record.');if(!confirm(`Delete ${attendance_ids.length} selected attendance record${attendance_ids.length===1?'':'s'}? A recovery snapshot will be created for administrators.`))return;const result=await send('/api/attendance/delete-selected','POST',{attendance_ids});notify(`${result.deleted} attendance records deleted.`);return renderApp();}
    case 'restore-backup':if(confirm(`Restore this ${control.dataset.type.replaceAll('_',' ')} snapshot? Existing records with the same database keys will not be replaced.`)){await send(`/api/backups/${encodeURIComponent(control.dataset.id)}/restore`,'POST',{});notify('Backup restored.');return renderApp();}return;
    case 'open-group':state.groupId=control.dataset.id;state.groupTab='overview';return renderView();
    case 'group-tab':state.groupTab=control.dataset.tab;return renderView();
    case 'back-groups':state.groupId='';return renderView();
    case 'global-search':return openGlobalSearch();
    case 'search-result':{const type=control.dataset.type,id=control.dataset.id,query=control.dataset.query;document.querySelector('#global-search')?.remove();if(type==='session')return takeAttendance(id);if(type==='group'){state.view='groups';state.groupId=id;state.groupTab='overview';return renderApp();}if(type==='student'){state.view='students';state.studentSearch=query;return renderApp();}if(type==='course'){state.view='courses';state.courseSearch=query;return renderApp();}if(type==='instructor'){state.view='instructors';state.instructorSearch=query;return renderApp();}return;}
    case 'mobile-menu':{const sidebar=document.querySelector('#sidebar'),isOpen=sidebar.classList.toggle('open');control.setAttribute('aria-expanded',String(isOpen));control.setAttribute('aria-label',isOpen?'Close navigation':'Open navigation');return;}
    case 'new-session':return openSessionModal();
    case 'view-attendance':return takeAttendance(control.dataset.id);
    case 'edit-session':return openSessionModal(control.dataset.id);
    case 'archive-session':if(confirm('Archive this session? Existing attendance will remain available for reports.')){await api(`/api/sessions/${encodeURIComponent(control.dataset.id)}`,{method:'DELETE'});notify('Session archived.');await renderApp();}return;
    case 'add-course':return openCourseModal();
    case 'edit-course':return openCourseModal({id:control.dataset.id,name:control.dataset.name,description:control.dataset.description,active:control.dataset.currentActive});
    case 'toggle-course':if(confirm(`${control.dataset.active==='0'?'Archive':'Restore'} this course?`)){await send(`/api/courses/${encodeURIComponent(control.dataset.id)}`,'PATCH',{active:control.dataset.active==='1'});notify('Course status updated.');await renderApp();}return;
    case 'add-group':return openGroupModal();
    case 'edit-group':{const group=(await api('/api/groups?active=all')).find(item=>item.id===control.dataset.id);if(!group)throw new Error('Group not found.');return openGroupModal(group);}
    case 'toggle-group':if(confirm(`${control.dataset.active==='0'?'Archive':'Restore'} this group?`)){await send(`/api/groups/${encodeURIComponent(control.dataset.id)}`,'PATCH',{active:control.dataset.active==='1'});notify('Group status updated.');await renderApp();}return;
    case 'add-student':return openStudentModal();
    case 'edit-student':return openStudentModal({id:control.dataset.id,full_name:control.dataset.name,group_id:control.dataset.group,active:control.dataset.active});
    case 'add-instructor':return addUserModal(true);
    case 'toggle-instructor':if(confirm(`${control.dataset.active==='0'?'Deactivate':'Reactivate'} this instructor account?`)){await send(`/api/instructors/${encodeURIComponent(control.dataset.id)}`,'PATCH',{active:control.dataset.active==='1'});notify('Instructor access updated.');await renderApp();}return;
    case 'add-user':return addUserModal(false);
    case 'toggle-user':if(confirm(`${control.dataset.active==='0'?'Disable':'Enable'} ${control.dataset.name}?`)){await send(`/api/users/${encodeURIComponent(control.dataset.id)}`,'PATCH',{active:control.dataset.active==='1'});notify('Account access updated.');await renderApp();}return;
    case 'reset-user':{const result=await send(`/api/users/${encodeURIComponent(control.dataset.id)}/reset-password`,'POST',{});return showCredentials({title:'Password reset',email:result.email,password:result.temporary_password});}
    case 'manage-permissions':{const current=JSON.parse(control.dataset.permissions||'[]'),choices=[['students.delete','Delete selected student records'],['attendance.delete','Delete attendance records'],['reports.export','Export attendance reports']],fields=`<fieldset class="field role-options"><legend>Additional instructor capabilities</legend>${choices.map(([permission,label])=>`<label><input type="checkbox" name="permissions" value="${permission}" ${current.includes(permission)?'checked':''}> ${label}</label>`).join('')}</fieldset><p class="help-text">Changes take effect immediately and are recorded in the audit log.</p>`;return openModal(`Capabilities · ${control.dataset.name}`,fields,'Save capabilities',async values=>{const permissions=Array.isArray(values.permissions)?values.permissions:values.permissions?[values.permissions]:[];await send(`/api/users/${encodeURIComponent(control.dataset.id)}/permissions`,'PUT',{permissions});return {refresh:true,message:'Instructor capabilities updated.'};});}
    case 'manage-roles':{const current=JSON.parse(control.dataset.roles||'[]'),html=`<fieldset class="field role-options"><legend>Access roles</legend>${['admin','instructor','viewer'].map(role=>`<label><input type="checkbox" name="roles" value="${role}" ${current.includes(role)?'checked':''}> ${roleNames[role]}</label>`).join('')}</fieldset>`;return openModal('Manage account roles',html,'Save roles',async values=>{if(!values.roles.length)throw new Error('Every staff account must retain at least one role.');if(values.roles.includes('viewer')&&values.roles.length>1)throw new Error('Viewer access must remain read-only and cannot be combined with other roles.');await send(`/api/users/${encodeURIComponent(control.dataset.id)}/roles`,'PUT',{roles:values.roles});return {refresh:true,message:'Account roles updated.'};});}
    case 'add-assignment':return openAssignmentModal();
    case 'remove-assignment':if(confirm('Remove this instructor assignment?')){await api(`/api/assignments/${encodeURIComponent(control.dataset.id)}`,{method:'DELETE'});notify('Assignment removed.');await renderApp();}return;
    case 'go-reports':state.view='attendance';return renderApp();
    case 'export-csv':{const link=document.createElement('a');link.href=`/api/export/attendance.csv?${new URLSearchParams(state.reportFilters||{})}`;link.download='attendance.csv';document.body.append(link);link.click();link.remove();return;}
    case 'export-xlsx':return downloadXlsx();
    case 'print-report':return printReport();
    case 'go-settings':state.view='settings';return renderApp();
    case 'select-excel-sheet':{const index=Number(control.dataset.index);if(!Number.isInteger(index)||index<0)throw new Error('Choose a valid worksheet.');if(control.dataset.scope==='import'){state.importWorkbookSheet=index;state.importMatrix=null;clearImportValidation();document.querySelector('#import-mapping').innerHTML='';const host=document.querySelector('#workbook-preview');if(host&&state.importWorkbook)host.innerHTML=`${workbookViewerMarkup(state.importWorkbook,state.importWorkbook.fileName,index,'import')}${button('continue-xlsx-mapping','Continue to column mapping',{primary:true,extra:'xlsx-continue'})}`;}else{state.workbookViewer.selectedSheet=index;const host=document.querySelector('#excel-workbook-preview');if(host)host.innerHTML=workbookViewerMarkup(state.workbookViewer,state.workbookViewer.fileName,index,'viewer');}return;}
    case 'continue-xlsx-mapping':{const matrix=workbookMatrix(state.importWorkbookSheet);startImportMapping(matrix,'XLSX');document.querySelector('#import-mapping')?.scrollIntoView({behavior:'smooth',block:'start'});notify('Worksheet ready. Map its columns before previewing the import.');return;}
    case 'update-import-matrix':{const text=document.querySelector('#import-text')?.value;if(!text)throw new Error('Paste or choose the rows to map.');startImportMapping(parseDelimitedText(text),state.importSource);return;}
    case 'preview-import':return runImportPreview();
    case 'confirm-import':return confirmImport();
    case 'audit-page':return loadAuditPage(Number(control.dataset.offset)||0);
    default:return;
  }
}

document.addEventListener('click',async event=>{
  const viewControl=event.target.closest('[data-view]');if(viewControl){event.preventDefault();state.view=viewControl.dataset.view;if(state.view!=='groups')state.groupId='';if(state.view==='import'&&!can('students.import'))state.importType='attendance';await renderApp();return;}
  const control=event.target.closest('[data-action]');if(!control)return;try{await handleAction(control.dataset.action,control);}catch(error){notify(error.message||'The operation could not be completed.',true);}
});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openGlobalSearch();}});

document.addEventListener('change',async event=>{
  const target=event.target;
  try{
    if(target.id==='theme-choice'){const result=await send('/api/profile/theme','PUT',{theme:target.value});state.user.theme=result.theme;setTheme(result.theme);notify('Appearance saved.');}
    else if(target.id==='import-type'){state.importType=target.value;state.importMatrix=null;state.importPreview=null;state.importWorkbook=null;state.importWorkbookSheet=0;await renderApp();}
    else if(target.id==='import-session'){state.importSession=target.value;clearImportValidation();}
    else if(target.id==='import-course'){clearImportValidation();state.importCourse=target.value;const groups=await api('/api/groups'),matching=groups.filter(group=>group.course_id===target.value),select=document.querySelector('#import-group');state.importGroup=matching[0]?.id||'';if(select)select.innerHTML=matching.map(group=>`<option value="${esc(group.id)}">${esc(group.name)}</option>`).join('');}
    else if(target.id==='import-group'){state.importGroup=target.value;clearImportValidation();}
    else if(target.name?.startsWith('map-'))clearImportValidation();
    else if(target.id==='import-file'&&target.files?.[0]){if(target.files[0].name.toLowerCase().endsWith('.xlsx')||target.files[0].name.toLowerCase().endsWith('.xls')){const preview=document.querySelector('#workbook-preview');if(preview)preview.innerHTML='<div class="loading-state">Loading workbook preview…</div>';document.querySelector('#import-mapping').innerHTML='';}await parseImportFile(target.files[0]);if(state.importWorkbook)notify('Workbook preview ready. Inspect it, choose a worksheet, then continue to column mapping.');else notify(`${state.importSource} file ready. Map each required column.`);}
    else if(target.id==='excel-file'&&target.files?.[0])await openWorkbookViewer(target.files[0]);
  }catch(error){if(target.id==='import-file'&&target.files?.[0]?.name.match(/\.xlsx?$/i)){const preview=document.querySelector('#workbook-preview');if(preview)preview.innerHTML=`<section class="panel error-panel"><strong>Workbook could not be opened</strong><p>${esc(error.message||'Choose a valid Excel workbook.')}</p></section>`;}notify(error.message||'Could not read this file.',true);}
});

async function openWorkbookViewer(file){
  const host=document.querySelector('#excel-workbook-preview');if(!host)return;
  if(file.size>5*1024*1024){host.innerHTML=`<section class="panel error-panel"><strong>Workbook is too large</strong><p>Choose a file smaller than 5 MB.</p></section>`;return;}
  host.innerHTML='<section class="panel loading-state">Loading workbook preview…</section>';
  try{const XLSX=await import('xlsx'),workbook=readWorkbook(XLSX,await file.arrayBuffer());state.workbookViewer={XLSX,workbook,fileName:file.name,selectedSheet:0};host.innerHTML=workbookViewerMarkup(state.workbookViewer,file.name,0,'viewer');}
  catch(error){state.workbookViewer=null;host.innerHTML=`<section class="panel error-panel"><strong>Workbook could not be opened</strong><p>${esc(error.message)}</p></section>`;}
}

document.addEventListener('input',event=>{
  if(event.target.id==='import-text')clearImportValidation();
  const search=event.target.closest('[data-excel-search]');if(!search)return;
  const section=search.closest('.excel-preview-panel'),query=search.value.toLocaleLowerCase(),rows=[...section.querySelectorAll('[data-excel-row]')];let shown=0;
  for(const row of rows){row.hidden=!row.dataset.search.includes(query);if(!row.hidden)shown++;}
  const count=section.querySelector('[data-excel-count]');if(count)count.textContent=`${shown} of ${rows.length} rows`;
});

document.addEventListener('submit',async event=>{
  const form=event.target;const kind=form.dataset.form;
  if(kind){event.preventDefault();try{
    if(kind==='students'){const params=paramsFromForm(form);state.studentSearch=params.get('q')||'';const rows=await api(`/api/students?${params}`);document.querySelector('#student-results').innerHTML=studentTable(rows,can('students.update'),can('students.delete'));}
    else if(kind==='course-search'){state.courseSearch=new FormData(form).get('q')?.toString()||'';await renderApp();}
    else if(kind==='instructor-search'){state.instructorSearch=new FormData(form).get('q')?.toString()||'';await renderApp();}
    else if(kind==='sessions'){const rows=await api(`/api/sessions?${paramsFromForm(form)}`);state.sessions=rows;document.querySelector('#session-results').innerHTML=sessionTable(rows);}
    else if(kind==='attendance'){state.reportFilters=Object.fromEntries(paramsFromForm(form));const rows=await api(`/api/attendance?${paramsFromForm(form)}`);document.querySelector('#attendance-results').innerHTML=attendanceTable(rows,can('attendance.delete'));}
    else if(kind==='audit'){const values=Object.fromEntries(paramsFromForm(form));await loadAuditPage(0,values);}
  }catch(error){notify(error.message,true);}return;}
  if(form.id==='workspace-settings-form'){event.preventDefault();try{const result=await send('/api/workspace','PUT',Object.fromEntries(new FormData(form)));state.workspaceName=result.name;document.title=result.name;await renderApp();notify('Workspace name updated.');}catch(error){notify(error.message,true);}return;}
  if(form.id==='password-settings-form'){event.preventDefault();const values=Object.fromEntries(new FormData(form)),message=document.querySelector('#settings-password-message');message.textContent='';if(values.new_password!==values.confirm_password){message.textContent='The new passwords do not match.';return;}try{await send('/api/auth/change-password','POST',{current_password:values.current_password,new_password:values.new_password});form.reset();message.textContent='Password updated. Other active sessions remain signed in.';notify('Password updated.');}catch(error){message.textContent=error.message;}}
});

async function start(){
  try{
    const workspace=await api('/api/workspace');state.workspaceName=workspace.name;state.setupRequired=workspace.setupRequired;document.title=workspace.name;
    try{const result=await api('/api/me');state.user=result.user;}catch(error){if(error.status!==401)throw error;renderAuth(state.setupRequired);return;}
    if(state.user.must_change_password){renderForcedPasswordChange();return;}await renderApp();
  }catch(error){app.innerHTML='<div class="loading-state"><strong>Workspace unavailable</strong><p>Check the database configuration and try refreshing in a moment.</p></div>';}
}
start();
